-- Band Blender community starters: 43 original style prompts, one or more per genre.
-- Generated by scripts/build-community-seed.mjs. Paste into the SQL editor and run once.
-- Re-running is safe: titles that already exist are skipped. No artist names, no user attached.
INSERT INTO public.public_prompts (title, style_tag, vocal_prompt, exclude_styles, genre_tags, recipe_note)
SELECT v.title, v.style_tag, v.vocal_prompt, v.exclude_styles, v.genre_tags, v.recipe_note
FROM (VALUES
  ('Warehouse house at sunrise', 'deep house, 122 bpm, four-on-the-floor kick, warm rolling bassline, filtered disco chords, crisp open hats, soulful female vocal chops, hypnotic, euphoric, late-night', '{"voice":"soulful female alto","delivery":"short repeated phrases, chopped","harmonies":"light stacked ad-libs","effects":"plate reverb, filter sweeps"}'::jsonb, 'trap hi-hats, dubstep wobble, distorted vocals', ARRAY['House']::text[], 'Starter: works best with a 2-line hook repeated through the drop.'),
  ('Dark peak-time techno', 'Driving peak-time techno at 132 BPM. A punchy kick and rumbling sub carry the groove while a distorted acid line twists overhead. Sparse metallic percussion fills the gaps, and one spoken phrase lands in the break, dry and upfront. Dark, relentless and wide, mixed loud and clean.', NULL, 'vocals in the verses, pop chorus, acoustic guitar', ARRAY['Techno']::text[], 'Studio brief format. Leave the lyrics box nearly empty for a club tool.'),
  ('Liquid drum & bass night drive', 'liquid drum and bass, 174 bpm, rolling breakbeats, deep reese bass, lush rhodes chords, airy pads, smooth female vocal, melancholic, uplifting chorus, clean modern mix', '{"voice":"smooth female soprano","delivery":"long legato lines over fast drums","harmonies":"airy doubles in the chorus","effects":"long hall reverb"}'::jsonb, 'harsh distortion, metal guitars, trap hi-hats', ARRAY['Drum & Bass']::text[], 'Starter: keep verses short; the breaks carry the energy.'),
  ('Halftime dubstep heavyweight', 'dubstep, 140 bpm halftime, heavy growling bass, sub drops, sharp snare on 3, cinematic intro pads, chopped vocal sample, aggressive, dark, punchy drums, wide stereo', '{"voice":"processed male vocal sample","delivery":"one-word shouts before the drop","harmonies":"none","effects":"pitch-shift, heavy delay"}'::jsonb, 'acoustic, folk, gentle piano ballad', ARRAY['Dubstep']::text[], 'Starter: use [Build] and [Drop] tags to steer the sections.'),
  ('Floating ambient morning', 'ambient, 70 bpm, slow evolving synth pads, soft granular textures, distant felt piano, field recording of rain, beatless, calm, spacious, meditative', NULL, 'drums, vocals, bass drops, distortion', ARRAY['Ambient']::text[], 'Instrumental. Turn on Structure only in Lyric Forge for section tags.'),
  ('Neon synthwave chase', 'synthwave, 110 bpm, gated reverb drums, pulsing analog bass arpeggio, bright brass synth lead, lush pads, male vocal with chorus effect, nostalgic, driving, 80s night drive', '{"voice":"clean male baritone","delivery":"steady, slightly detached","harmonies":"octave doubles in the chorus","effects":"chorus, gated reverb"}'::jsonb, 'trap hi-hats, modern autotune, acoustic guitar', ARRAY['Synthwave']::text[], 'Starter: an 8-bar synth solo after chorus 2 suits this sound.'),
  ('Smoky late-night trip-hop', 'Dark trip-hop at 84 BPM with a slow, heavy swing. Dusty breakbeat drums and deep sub bass sit under eerie Rhodes chords and vinyl crackle. A close-miked, dry female vocal sits upfront above the band. Verses stay sparse; the chorus adds strings.', '{"voice":"smoky female alto","delivery":"half-spoken verses, sung chorus","harmonies":"low doubles on the hook","effects":"short room, light tape delay"}'::jsonb, 'autotune, trap hi-hats, buried vocals, fade-out', ARRAY['Trip-hop']::text[], 'Studio brief format with the vocal placed upfront.'),
  ('Glitchy IDM daydream', 'IDM, 100 bpm, intricate glitch percussion, granular chopped melodies, warm sub bass, music-box bells, shifting time feel, playful, curious, detailed stereo field', NULL, 'four-on-the-floor kick, pop chorus, distorted guitars', ARRAY['IDM']::text[], 'Instrumental. Raise complexity in Band Blender''s sliders for more detail.'),
  ('Laid-back west coast hip-hop', 'hip-hop, 92 bpm, laid-back swing, punchy kick, crisp snare, rubbery synth bass, smooth electric piano, confident male rap, sunny, relaxed, polished mix', '{"voice":"confident male baritone rap","delivery":"relaxed flow, behind the beat","harmonies":"sung hook doubles","effects":"dry, slight room"}'::jsonb, 'EDM drop, metal guitars, autotune', ARRAY['Hip-hop']::text[], 'Starter: 16-bar verses and an 8-bar sung hook.'),
  ('Dark trap anthem', 'dark trap, 140 bpm, rolling 808 bass, fast hi-hat triplets, hard snare, eerie bell melody, choir pad, aggressive male rap, menacing, heavy low end, clean vocal on top', '{"voice":"gritty male rap","delivery":"punchy, rhythmic, ad-libs between lines","harmonies":"stacked chorus chants","effects":"light saturation"}'::jsonb, 'acoustic guitar, folk, jazz brushes', ARRAY['Trap']::text[], 'Starter: put ad-libs in (parentheses) to keep them in the background.'),
  ('UK drill late night', 'UK drill, 142 bpm, sliding 808 bass, skippy hi-hats, syncopated snares, dark piano and strings, cold male rap, tense, cinematic, punchy mix', '{"voice":"low male rap","delivery":"clipped, conversational flow","harmonies":"none","effects":"dry, upfront"}'::jsonb, 'happy pop, acoustic, reggae', ARRAY['Drill']::text[], 'Starter: keep the hook short and chantable.'),
  ('Silky slow-jam R&B', 'R&B slow jam, 68 bpm, soft programmed drums, deep sub bass, lush electric piano, warm strings, sensual female vocal with runs, intimate but upfront, romantic, glossy mix', '{"voice":"warm female mezzo","delivery":"breathy verses, belted runs in the chorus","harmonies":"stacked three-part harmonies","effects":"close-miked, plate reverb"}'::jsonb, 'rock guitars, EDM drop, harsh highs', ARRAY['R&B']::text[], 'Starter: an ''intimate but upfront'' vocal avoids Suno burying a soft voice.'),
  ('Neo-soul Sunday', 'neo-soul, 86 bpm, loose behind-the-beat drums, round bass guitar, jazzy Rhodes chords, muted guitar licks, warm male falsetto, laid-back, organic, live band feel', '{"voice":"warm male falsetto","delivery":"relaxed, conversational phrasing","harmonies":"soft gospel-style backing","effects":"vintage room"}'::jsonb, 'trap hi-hats, EDM synths, autotune', ARRAY['Neo-Soul']::text[], 'Starter: lower the energy slider to keep the groove loose.'),
  ('Rainy window lo-fi', 'lo-fi hip-hop, 78 bpm, dusty swung drums, warm upright bass, mellow jazz piano chords, vinyl crackle, soft rain, tape wobble, cozy, nostalgic, study beat', NULL, 'vocals, EDM drop, distorted guitars', ARRAY['Lo-fi Hip-hop']::text[], 'Instrumental study beat. Ask for 2 to 3 minutes in the length planner.'),
  ('Golden-era boom bap', 'boom bap, 90 bpm, hard dusty kick and snare, chopped soul sample, jazzy bass line, record scratches, storytelling male rap, gritty, head-nodding, raw mix', '{"voice":"clear male rap","delivery":"storytelling, on the beat","harmonies":"none","effects":"dry"}'::jsonb, 'trap hi-hats, 808 slides, autotune', ARRAY['Boom Bap']::text[], 'Starter: give the scratches their own [Instrumental Break].'),
  ('Arena rock anthem', 'arena rock, 128 bpm, big punchy drums, driving power chords, melodic lead guitar, solid bass, powerful male vocal, anthemic chorus, crowd gang vocals, bright, triumphant', '{"voice":"powerful male tenor","delivery":"grit in the verses, open belting in the chorus","harmonies":"gang vocals on the hook","effects":"medium hall"}'::jsonb, 'synth bass, trap hi-hats, lo-fi', ARRAY['Rock']::text[], 'Starter: the Heavy but clear chip keeps guitars from smearing the vocal.'),
  ('Jangly indie rock summer', 'indie rock, 120 bpm, jangly clean guitars, melodic bass, tight drums, warm male vocal, wistful, upbeat, garage warmth, catchy chorus', '{"voice":"warm male baritone","delivery":"casual verses, lifted chorus","harmonies":"light doubles","effects":"short slapback"}'::jsonb, 'autotune, EDM drop, trap hi-hats', ARRAY['Indie Rock']::text[], 'Starter: compare the tag list with a Studio brief on this one.'),
  ('Moody alternative build', 'Alternative rock at 100 BPM that starts quiet and builds. Muted guitar arpeggios and a steady bass carry the verses, then fuzzed guitars and crashing drums open the chorus. A raw male vocal sits upfront the whole way. Moody, cathartic, wide mix.', '{"voice":"raw male baritone","delivery":"restrained verses, strained chorus","harmonies":"octave double in the last chorus","effects":"dry verses, roomier chorus"}'::jsonb, 'pop synths, trap hi-hats, fade-out', ARRAY['Alternative']::text[], 'Studio brief format, using the Arc line for quiet verses and a loud chorus.'),
  ('Melodic metal with clean chorus', 'melodic metal, 150 bpm, double-kick drums, tight palm-muted riffs, soaring guitar harmonies, growled verses, clean male chorus, epic, heavy but defined low end, punchy drums', '{"voice":"growl and clean male tenor","delivery":"growled verses, melodic clean chorus","harmonies":"doubled clean chorus","effects":"tight room"}'::jsonb, 'pop synths, lo-fi, acoustic ballad', ARRAY['Metal']::text[], 'Starter: cue sections with [Growled] and [Clean] for the vocal switch.'),
  ('Slow-burn post-rock', 'post-rock, 90 bpm, shimmering tremolo guitars, swelling crescendos, patient drums, deep bass, glockenspiel, instrumental, cinematic, hopeful, huge final climax', NULL, 'vocals, EDM drop, trap hi-hats', ARRAY['Post-Rock']::text[], 'Instrumental. A 5-minute plan with one long build works best.'),
  ('Fast and loud punk', 'punk rock, 180 bpm, fast downstroke guitars, driving bass, frantic drums, shouted male vocals, gang chorus, raw, energetic, short and loud', '{"voice":"shouted male vocal","delivery":"urgent, slightly off-key on purpose","harmonies":"gang shouts","effects":"dry"}'::jsonb, 'synth pads, ballad, autotune', ARRAY['Punk']::text[], 'Starter: keep it under 2:30; punk songs end fast.'),
  ('Sludgy 90s grunge', 'grunge, 95 bpm, sludgy distorted guitars, quiet verses and loud chorus, thick bass, heavy drums, raspy male vocal, angsty, raw, roomy mix', '{"voice":"raspy male baritone","delivery":"mumbled verses, screamed chorus","harmonies":"none","effects":"room reverb"}'::jsonb, 'pop synths, trap hi-hats, autotune', ARRAY['Grunge']::text[], 'Starter: describe the sound, never name a band; Suno blocks artist names.'),
  ('Dreamy shoegaze haze', 'shoegaze, 105 bpm, walls of reverb-drenched guitars, fuzzy bass, steady drums, soft female vocal set close and clear above the guitars, hazy, euphoric, dreamy', '{"voice":"soft female soprano","delivery":"gentle, floating","harmonies":"airy doubles","effects":"close-miked under heavy guitar wash"}'::jsonb, 'trap hi-hats, rap, dry vocals', ARRAY['Shoegaze']::text[], 'Starter: soft vocals need placement words, or they vanish in the guitars.'),
  ('Bright radio pop', 'pop, 118 bpm, punchy claps, bright synth chords, bouncy bass, catchy female vocal, big hook in the first five words, upbeat, glossy, modern radio mix', '{"voice":"bright female soprano","delivery":"crisp, rhythmic verses, soaring chorus","harmonies":"stacked chorus","effects":"polished, light delay"}'::jsonb, 'metal guitars, lo-fi, long instrumental intro', ARRAY['Pop']::text[], 'Starter: add [Instrumental Intro] only if you want a lead-in.'),
  ('Glossy synth-pop heartbreak', 'synth-pop, 112 bpm, punchy electronic drums, pulsing synth bass, sparkling arpeggios, wistful male vocal, bittersweet, danceable, clean mix', '{"voice":"wistful male tenor","delivery":"smooth, slightly breathy but upfront","harmonies":"falsetto doubles","effects":"chorus, plate reverb"}'::jsonb, 'acoustic guitar, trap hi-hats, distortion', ARRAY['Synth-pop']::text[], 'Starter: sad lyrics over a danceable beat is the classic move.'),
  ('Hazy dream pop drift', 'dream pop, 90 bpm, shimmering synths, chorused guitars, soft drum machine, warm bass, close-miked dry female vocal upfront and clearly above the band, hazy, tender, nostalgic', '{"voice":"soft female alto","delivery":"gentle, intimate","harmonies":"airy doubles","effects":"close-miked, light reverb"}'::jsonb, 'rap, metal, buried vocals', ARRAY['Dream Pop']::text[], 'Starter: shows the vocal-placement fix in action.'),
  ('Art-pop strange beauty', 'art pop, 96 bpm, off-kilter drum programming, warped synths, string stabs, unusual chord changes, expressive female vocal, theatrical, adventurous, detailed mix', '{"voice":"expressive female mezzo","delivery":"dramatic dynamics, spoken asides","harmonies":"choir-like stacks","effects":"varied by section"}'::jsonb, 'generic pop chorus, trap hi-hats, country', ARRAY['Art Pop']::text[], 'Starter: try v6-wild for more surprising takes.'),
  ('Sugar-rush hyperpop', 'hyperpop, 160 bpm, distorted kicks, glitchy bitcrushed synths, sugary melodies, pitched-up vocals, chaotic drops, playful, maximal, loud', '{"voice":"pitched-up androgynous vocal","delivery":"bratty, fast","harmonies":"chipmunk doubles","effects":"heavy pitch correction, bitcrush"}'::jsonb, 'acoustic, folk, slow ballad', ARRAY['Hyperpop']::text[], 'Starter: here autotune is part of the sound, so don''t exclude it.'),
  ('K-pop dance break', 'K-pop, 124 bpm, hard-hitting drums, punchy synth bass, bright brass hits, rap verse into soaring chorus, mixed group vocals, energetic dance break, polished, confident', '{"voice":"mixed group vocals","delivery":"rap verse, sung pre-chorus, chant chorus","harmonies":"big group harmonies","effects":"polished, tight"}'::jsonb, 'lo-fi, acoustic folk, slow tempo', ARRAY['K-pop']::text[], 'Starter: label parts like [Rap Verse] and [Dance Break].'),
  ('Campfire folk story', 'folk, 96 bpm, fingerpicked acoustic guitar, soft upright bass, light brushed drums, harmonica, warm male vocal, storytelling, honest, intimate but upfront', '{"voice":"warm male baritone","delivery":"storytelling, plain","harmonies":"light second voice in the chorus","effects":"dry room"}'::jsonb, 'synths, EDM drop, autotune', ARRAY['Folk']::text[], 'Starter: concrete details in the lyrics matter most here.'),
  ('Stomp-and-clap indie folk', 'indie folk, 108 bpm, strummed acoustic guitars, stomp and clap percussion, banjo, upright piano, group vocals, hopeful, rousing chorus, warm live feel', '{"voice":"earnest mixed vocals","delivery":"rousing, shouted chorus","harmonies":"big group ''hey'' chants","effects":"roomy"}'::jsonb, 'synth bass, trap hi-hats, distortion', ARRAY['Indie Folk']::text[], 'Starter: put (hey!) ad-libs in parentheses on the hook.'),
  ('Modern country heartache', 'modern country, 84 bpm, acoustic guitar, pedal steel, warm bass, steady drums, twangy male vocal, heartbreak ballad, big emotional chorus, polished Nashville mix', '{"voice":"twangy male baritone","delivery":"conversational verses, soaring chorus","harmonies":"high harmony in the chorus","effects":"light plate"}'::jsonb, 'rap, EDM drop, metal guitars', ARRAY['Country']::text[], 'Starter: a twist in the last chorus line is a country staple.'),
  ('Dusty Americana highway', 'americana, 100 bpm, open-tuned acoustic guitar, slide guitar, upright bass, brushed drums, organ, weathered female vocal, dusty, reflective, roomy live recording', '{"voice":"weathered female alto","delivery":"unhurried, plainspoken","harmonies":"soft male harmony","effects":"room"}'::jsonb, 'synths, trap hi-hats, autotune', ARRAY['Americana']::text[], 'Starter: live room words keep it organic.'),
  ('Bluegrass breakdown', 'bluegrass, 140 bpm, fast banjo rolls, flatpicked guitar, fiddle, mandolin chop, upright bass, high lonesome male vocal, tight harmonies, joyful, acoustic', '{"voice":"high lonesome male tenor","delivery":"bright, driving","harmonies":"three-part close harmony","effects":"dry"}'::jsonb, 'drums, synths, electric guitar', ARRAY['Bluegrass']::text[], 'Starter: give each instrument a short break with [Banjo Solo] and so on.'),
  ('Piano singer-songwriter', 'singer-songwriter, 72 bpm, solo piano, soft cello, gentle female vocal close-miked and upfront, honest, vulnerable, minimal arrangement, quiet but full verses', '{"voice":"gentle female alto","delivery":"intimate, clear diction","harmonies":"none","effects":"close-miked, small room"}'::jsonb, 'drums, EDM drop, distortion', ARRAY['Singer-Songwriter']::text[], 'Starter: ''quiet but full verses'' stops the song dropping to near silence.'),
  ('Smoky jazz club ballad', 'jazz ballad, 70 bpm, brushed drums, walking upright bass, lush piano voicings, muted trumpet, smoky female vocal close-miked and upfront, late-night, intimate, warm room recording', '{"voice":"smoky female contralto","delivery":"behind the beat, conversational","harmonies":"none","effects":"warm room"}'::jsonb, 'synths, trap hi-hats, distorted guitars', ARRAY['Jazz']::text[], 'Starter: a muted trumpet solo after verse 2 fits the mood.'),
  ('Classic soul strut', 'classic soul, 104 bpm, tight drums, melodic bass, horn section stabs, organ, tambourine, gritty male vocal, joyful, call and response, warm analog mix', '{"voice":"gritty male tenor","delivery":"powerful, preacher-like ad-libs","harmonies":"female backing call and response","effects":"plate reverb"}'::jsonb, 'synth bass, trap hi-hats, autotune', ARRAY['Soul']::text[], 'Starter: write backing replies in (parentheses).'),
  ('Tight funk groove', 'funk, 106 bpm, tight syncopated drums, slap bass, scratchy rhythm guitar, horn hits, clavinet, energetic male vocal, groovy, playful, punchy dry mix', '{"voice":"energetic male tenor","delivery":"rhythmic, shouted hooks","harmonies":"group chants","effects":"dry"}'::jsonb, 'ballad, ambient pads, trap hi-hats', ARRAY['Funk']::text[], 'Starter: raise energy and complexity for a busier groove.'),
  ('Late-night electric blues', 'electric blues, 76 bpm, slow shuffle, crying lead guitar, hammond organ, walking bass, brushed snare, gravelly male vocal, soulful, weary, live club sound', '{"voice":"gravelly male baritone","delivery":"call and answer with the guitar","harmonies":"none","effects":"room"}'::jsonb, 'synths, EDM drop, autotune', ARRAY['Blues']::text[], 'Starter: 12-bar verses; leave space after each line for a guitar answer.'),
  ('Uplifting gospel choir', 'gospel, 92 bpm, hammond organ, piano, driving drums, bass guitar, full choir, powerful female lead, call and response, uplifting, joyful, big final key change', '{"voice":"powerful female lead with choir","delivery":"building from calm to shouting joy","harmonies":"full choir responses","effects":"church hall reverb"}'::jsonb, 'trap hi-hats, distortion, lo-fi', ARRAY['Gospel']::text[], 'Starter: cue the key change with [Key Change] before the last chorus.'),
  ('Epic cinematic trailer', 'cinematic trailer, 120 bpm, booming taiko drums, pulsing low strings, brass swells, choir hits, rising tension, huge climax, dramatic silence before the drop, epic, wide', NULL, 'pop vocals, lo-fi, acoustic guitar', ARRAY['Cinematic']::text[], 'Instrumental. Use [Build], [Silence] and [Climax] as section tags.'),
  ('Sunny afrobeat groove', 'afrobeats, 104 bpm, bouncy syncopated percussion, log drum bass, bright guitar riffs, warm synth pads, smooth male vocal, sunny, danceable, polished mix', '{"voice":"smooth male tenor","delivery":"melodic, laid-back","harmonies":"female backing hook","effects":"light reverb"}'::jsonb, 'metal guitars, ballad, trap hi-hats', ARRAY['Afrobeat']::text[], 'Starter: repeat the hook more than you think; it''s a dance genre.'),
  ('Late-night bossa nova', 'bossa nova, 120 bpm, nylon-string guitar, soft brushed drums, upright bass, flute, gentle female vocal close and upfront, relaxed, warm, intimate', '{"voice":"gentle female alto","delivery":"soft, almost whispered, but clear","harmonies":"none","effects":"close-miked"}'::jsonb, 'distortion, trap hi-hats, EDM drop', ARRAY['Bossa Nova']::text[], 'Starter: switch on Spanish or Portuguese lyrics if you write them.')
) AS v(title, style_tag, vocal_prompt, exclude_styles, genre_tags, recipe_note)
WHERE NOT EXISTS (SELECT 1 FROM public.public_prompts p WHERE p.title = v.title);
